1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.rest.controller.OwnerIdentity;
13	import org.springframework.samples.petclinic.service.BulkSignupWarningEvaluator;
14	import org.springframework.samples.petclinic.service.MembershipLevelEvaluator;
15	
16	import java.util.Collection;
17	import java.util.List;
18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public abstract class OwnerMapper {
24	
25	    @Autowired
26	    protected BulkSignupWarningEvaluator bulkSignupWarningEvaluator;
27	
28	    @Autowired
29	    protected MembershipLevelEvaluator membershipLevelEvaluator;
30	
31	    @Autowired
32	    protected OwnerIdentity ownerIdentity;
33	
34	    @Mapping(target = "identityKey", expression = "java(owner == null ? null : ownerIdentity.key(owner))")
35	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
36	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
37	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
38	    @Mapping(target = "membershipLevel", expression = "java(membershipLevelEvaluator.levelFor(owner))")
39	    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.model.Locality.forOwner(owner))")
40	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarningEvaluator.isWarranted(owner))")
41	    @Mapping(target = "contactPreference", expression = "java(org.springframework.samples.petclinic.model.ContactPreference.forOwner(owner))")
42	    public abstract OwnerDto toOwnerDto(Owner owner);
43	
44	    /**
45	     * Formats an owner's membership number as {@code "<customerCode>-M<YY>"}, where
46	     * {@code YY} is the last two digits of the registration date's year
47	     * (e.g. {@code "LON-SMI-0007-M26"}). Returns {@code null} until both the customer code
48	     * and registration date have been assigned.
49	     */
50	    protected String formatMembershipNumber(Owner owner) {
51	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
52	            return null;
53	        }
54	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
55	    }
56	
57	    /**
58	     * Formats an owner's stored names as {@code "LastName, FirstName"} for display.
59	     */
60	    protected String formatDisplayName(Owner owner) {
61	        if (owner == null) {
62	            return null;
63	        }
64	        return owner.getLastName() + ", " + owner.getFirstName();
65	    }
66	
67	    /**
68	     * Builds an owner's initials as the upper-cased first letters of the first and last
69	     * name, dot-separated with a trailing dot (e.g. {@code "J.S."}).
